public sealed class Order
{
    public Guid Id { get; private init; } = Guid.NewGuid();
    public OrderStatus Status { get; private set; } = OrderStatus.Draft;

    private readonly List<OrderLine> _lines = new();
    public IReadOnlyList<OrderLine> Lines => _lines.AsReadOnly();

    public Result AddLine(Product product, int quantity)
    {
        if (Status != OrderStatus.Draft)
            return Result.Failure("Cannot modify a confirmed order.");

        _lines.Add(new OrderLine(product, quantity));
        return Result.Success();
    }

    public Result Confirm()
    {
        if (!_lines.Any())
            return Result.Failure("An order must have at least one line.");

        Status = OrderStatus.Confirmed;
        return Result.Success();
    }
}

public sealed class CreateOrderHandler : IRequestHandler<CreateOrderCommand, Guid>
{
    private readonly IOrderRepository _orders;
    private readonly IUnitOfWork _unitOfWork;

    public CreateOrderHandler(IOrderRepository orders, IUnitOfWork unitOfWork)
    {
        _orders = orders;
        _unitOfWork = unitOfWork;
    }

    public async Task<Guid> Handle(
        CreateOrderCommand command, CancellationToken ct)
    {
        var order = Order.Create(command.CustomerId);

        foreach (var line in command.Lines)
            order.AddLine(line.Product, line.Quantity);

        await _orders.AddAsync(order, ct);
        await _unitOfWork.SaveChangesAsync(ct);

        return order.Id;
    }
}
